window.importReadingProgress=function(raw){if(raw?.version!==1||!raw.records||!raw.words)throw Error('format');const imported=cleanState(raw);for(const [id,r] of Object.entries(imported.records)){const old=state.records[id];if(old){r.reads=Math.max(r.reads,old.reads);for(const t of ['meaning','cloze','build'])r.passed[t]=r.passed[t]||old.passed[t];}state.records[id]=r;}Object.assign(state.words,imported.words);if(raw.drafts?.version===2&&raw.drafts.entries){for(const [key,x]of Object.entries(raw.drafts.entries)){const split=key.lastIndexOf(':'),id=key.slice(0,split),kind=key.slice(split+1),valid=validDialogueDraft(lookup.get(id),kind,x);if(valid)dialogueDrafts.entries[key]=valid;}exercise=restoreDialogueDraft(current.id,type);stashDialogueDraft();}save();render();};
$('#export-progress').onclick=async()=>{if(window.HanziPractice?.ready)await window.HanziPractice.ready;if(window.HanziPaper?.ready)await window.HanziPaper.ready;const full=window.HanziPractice?{format:'hanzi-full-progress',version:1,reading:{...state,drafts:dialogueDrafts},practice:window.HanziPractice.snapshot(),paper:window.HanziPaper?.snapshot()}:state;const blob=new Blob([JSON.stringify(full,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hanzi-full-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#import-progress').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.format==='hanzi-full-progress'&&window.HanziPractice)await window.HanziPractice.importBackup(file);else{window.importReadingProgress(raw);toast('Reading progress imported and merged.');}}catch{toast('Could not import that progress file.');}e.target.value='';};
// Recover legacy attempts and the last independently saved activity.
try{const old=JSON.parse(localStorage.getItem('hanzi-dialogue-draft-v1'));if(old&&validDialogueDraft(lookup.get(old.id),old.type,old.exercise)&&!dialogueDrafts.entries[old.id+':'+old.type]){dialogueDrafts.entries[old.id+':'+old.type]=old.exercise;if(!dialogueDrafts.last)dialogueDrafts.last={id:old.id,type:old.type};}}catch{}
if(dialogueDrafts.last?.id===current.id&&['meaning','cloze','build'].includes(dialogueDrafts.last.type))type=dialogueDrafts.last.type;
exercise=restoreDialogueDraft(current.id,type);
render();
